css:
&.slide.tpl {
& { padding:58px 80px 56px; display:flex; flex-direction:column; gap:20px; }
header { flex:none; display:flex; align-items:baseline; gap:28px; flex-wrap:wrap; }
header p { order:2; color:var(--accent); font:600 21px/1 var(--font-mono,var(--mono)); letter-spacing:.14em; text-transform:uppercase; margin:0; padding:10px 16px; border:1.5px solid color-mix(in srgb,var(--accent) 55%,transparent); border-radius:999px; }
header h2 { order:1; font-size:56px; line-height:1.08; margin:0; max-width:46ch; text-wrap:balance; }
header :empty { display:none; }
header:has(h2:empty):has(p:empty) { display:none; }
.rib-stage { position:relative; flex:1; min-height:0; counter-reset:steg; }
figure { position:absolute; inset:0; margin:0; display:grid; grid-template-rows:minmax(0,1fr) auto; gap:18px; }
figure img { width:100%; height:100%; min-height:0; object-fit:contain; }
figcaption { display:flex; align-items:center; gap:26px; min-height:96px; padding:18px 30px; font-size:29px; line-height:1.3; background:color-mix(in srgb,var(--surface) 82%,transparent); border:1px solid var(--line); border-left:5px solid var(--accent); border-radius:calc(var(--radius) * .6); }
.image-step { counter-increment:steg; }
figcaption b { display:flex; align-items:center; gap:14px; flex:none; max-width:520px; color:var(--accent); font-weight:650; }
.image-step figcaption b::before { content:counter(steg); display:grid; place-items:center; flex:none; width:44px; height:44px; border-radius:50%; background:var(--accent); color:var(--bg); font:700 22px/1 var(--font-mono,var(--mono)); }
figcaption span { flex:1; color:var(--ink); }
.rib-base figcaption { border-left-color:var(--muted); }
.rib-base figcaption span { color:var(--muted); }
.rib-base figcaption:has(span:empty) { visibility:hidden; }
.image-step { visibility:hidden; opacity:0!important; transition:opacity .28s ease; }
.image-step.in,.image-step:not([data-step]) { visibility:inherit; opacity:1!important; }
.image-step:has(~.image-step.in),.image-step:not([data-step]):has(~.image-step),.rib-base:has(~.image-step.in),.rib-base:has(~.image-step:not([data-step])) { visibility:hidden; opacity:0!important; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }
}
